-- SMART HOME SECURITY & MONITORING (8 products)
('eufy-solo-cam-s220-solar', 'eufy SoloCam S220 Solar Security Camera 2K Wireless - White', 'smart-home', 95000, 92900, 78000, 20, 0.65, '/assets/products/eufy-solocam-s220.webp', 'Forever power from the sun with the integrated solar panel that keeps the battery charged indefinitely. The 2K resolution with AI human detection eliminates false alerts, while the built-in 8GB local storage requires no monthly subscription fees ever.', 1, unixepoch('2026-06-16'), 1, 78000, '/assets/products/eufy-solocam-s220.webp', 88000, 4.5, 1, 'eufy', 1, 1),

