('reolink-doorbell-wifi-2k', 'Reolink Video Doorbell WiFi 2K with Chime & AI Detection - Black', 'smart-home', 65000, 63900, 52000, 15, 0.28, '/assets/products/reolink-doorbell-wifi.webp', 'Know who''s at your door before opening it with 2K HD video, AI person detection that reduces false alerts, and two-way audio. The included chime, 180° diagonal field of view, and dual-band WiFi ensure you never miss a visitor, delivery, or unexpected guest.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/reolink-doorbell-wifi.webp', 59000, 4.4, 0, 'Reolink', 1, 1),

('imou-cell-4g-camera-outdoor', 'Imou Cell 4G Solar Outdoor Camera with SIM Slot - No WiFi Needed', 'smart-home', 95000, 92900, 78000, 10, 0.95, '/assets/products/imou-cell-4g-camera.webp', 'Perfect for remote Nigerian locations without WiFi. Insert a 4G SIM card and the camera connects anywhere there''s cellular signal, with a solar panel keeping the battery charged. 2K resolution, AI detection, and cloud plus local storage options provide complete security.', 1, unixepoch('2026-06-16'), 1, 78000, '/assets/products/imou-cell-4g-camera.webp', 88000, 4.4, 0, 'Imou', 1, 1),

